package com.company.platform.commerce.infrastructure;
import org.springframework.context.annotation.*; import org.springframework.kafka.core.*; import java.util.*;
@Configuration public class KafkaConfiguration { @Bean ProducerFactory<String,Object> producerFactory(){Map<String,Object> p=new HashMap<>();p.put(org.apache.kafka.clients.producer.ProducerConfig.BOOTSTRAP_SERVERS_CONFIG,System.getenv().getOrDefault("KAFKA_BOOTSTRAP_SERVERS","localhost:9092"));p.put(org.apache.kafka.clients.producer.ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG,org.apache.kafka.common.serialization.StringSerializer.class);p.put(org.apache.kafka.clients.producer.ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG,org.springframework.kafka.support.serializer.JsonSerializer.class);return new DefaultKafkaProducerFactory<>(p);} @Bean KafkaTemplate<String,Object> kafkaTemplate(ProducerFactory<String,Object> f){return new KafkaTemplate<>(f);} }
